const $ = (id) => document.getElementById(id);
const reducedMotion = matchMedia('(prefers-reduced-motion: reduce)').matches;
let toastTimer, audioContext, soundEnabled = false;
function toast(message) { $('toast').textContent = message; $('toast').classList.add('show'); clearTimeout(toastTimer); toastTimer = setTimeout(() => $('toast').classList.remove('show'), 3500); }
function chime() { if (!soundEnabled) return; try { audioContext ||= new (window.AudioContext || window.webkitAudioContext)(); audioContext.resume(); [523.25,659.25,783.99].forEach((frequency,i) => { const oscillator=audioContext.createOscillator(),gain=audioContext.createGain(),now=audioContext.currentTime+i*.08; oscillator.type='sine'; oscillator.frequency.value=frequency; gain.gain.setValueAtTime(0,now); gain.gain.linearRampToValueAtTime(.04,now+.025); gain.gain.exponentialRampToValueAtTime(.001,now+.3); oscillator.connect(gain); gain.connect(audioContext.destination); oscillator.start(now); oscillator.stop(now+.32); }); } catch { soundEnabled=false; $('sound').setAttribute('aria-pressed','false'); $('sound').querySelector('span').textContent='Bunyi: off'; } }
function hearts(count=30) { chime(); if(reducedMotion) return; const icons=['💖','💕','💗','♥','♡','💌','✨']; for(let i=0;i<count;i++) { if($('particles').childElementCount>=90) break; const heart=document.createElement('span'); heart.className='particle'; heart.textContent=icons[Math.floor(Math.random()*icons.length)]; heart.style.setProperty('--left',`${Math.random()*100}%`); heart.style.setProperty('--size',`${16+Math.random()*23}px`); heart.style.setProperty('--duration',`${2+Math.random()*3}s`); heart.style.setProperty('--drift',`${Math.random()*180-90}px`); $('particles').append(heart); setTimeout(()=>heart.remove(),5100); } }
$('rain').addEventListener('click',()=>{hearts(65);toast('Prakiraan cuaca: 100% kemungkinan jatuh cinta sama Mareta 💖');});
$('sound').addEventListener('click',()=>{soundEnabled=!soundEnabled; $('sound').setAttribute('aria-pressed',String(soundEnabled)); $('sound').querySelector('span').textContent=`Bunyi: ${soundEnabled?'on':'off'}`;chime();});
$('hug').addEventListener('click',()=>{hearts(35);toast('Peluk virtual terkirim. Durasi: sampai kamu senyum 🫂💗');});
const quiz=[
  {question:'Kenapa bulan gak jatuh ke bumi?',options:['Karena gravitasi.','Karena nunggu Mareta bilang “sini”.','Karena takut jadi pihak ketiga.'],feedback:['Secara ilmiah mungkin. Secara bucin: orbit hatiku tetap Mareta. 🌙','BENAR SECARA KEGOMBALAN! Bulan aja nunggu, apalagi aku. 🌙💗','Teori baru diterima. NASA sekarang singkatan dari Naksir Aku Sama mAreta. 🚀']},
  {question:'Kalau 1 + 1 = 2, aku + Mareta = ...?',options:['Kita.','Satu server penuh emoji hati.','Laporan gangguan: terlalu gemas.'],feedback:['Jawaban diterima. Kita. Dengan tanda hati di belakangnya. ♡','Server kepanasan. Penyebab: sayang yang tidak dikompres. 💾💖','Petugas sudah datang. Ternyata petugasnya juga ikut cieee. 🚨']},
  {question:'Apa bedanya Mareta sama charger?',options:['Charger ada kabelnya.','Mareta ngecas hatiku tanpa colokan.','Charger gak bisa diajak kangen-kangenan.'],feedback:['Betul. Kalau kamu, nyambungnya langsung ke hati. 🔌','Baterai hati: 999%. Mohon berhenti terlalu lucu. 🔋💗','Charger: “aku menyerah, sainganku terlalu manis.” 🥲']},
  {question:'Jika ikan hidup di air, aku hidup di ...?',options:['Planet bumi, harusnya.','Notifikasi dari Mareta.','Skenario ketemu kamu lagi.'],feedback:['Betul. Tapi pusat tata surya kebucinanku ya kamu. 🌏','Ting! Satu pesan darimu, satu hari jadi lebih manis. 💬','Jawaban diterima oleh Kementerian Kangen Nasional. 💌']},
  {question:'Kenapa keyboard ada tombol M?',options:['Supaya bisa ngetik Mareta.','Karena tombol “aku sayang kamu” kepanjangan.','Karena M itu milik hati ini.'],feedback:['Jawaban mutlak. Huruf favorit hari ini resmi ditetapkan. ⌨️','Usulan tombol baru: Mareta Mode. Sekali tekan langsung bucin. 💘','Hak milik diterima. Sertifikatnya berbentuk hati. 📜']},
  {question:'Teka-teki terakhir: siapa yang bikin aku bikin website sealay ini?',options:['Mareta.','Mareta, tapi pakai huruf kapital.','MARETA SAYANGGGGG 💖'],feedback:['Terdakwa dinyatakan terlalu menggemaskan. 💗','MARETA. Suara di kepala ini pakai caps lock. 💖','UJIAN SELESAI! Kamu lulus dengan predikat: kesayanganku. 🏆💘']}
];
let questionIndex=0,answered=false;
function renderQuiz() { const item=quiz[questionIndex]; answered=false; $('quiz-count').textContent=`SOAL ${String(questionIndex+1).padStart(2,'0')} / ${String(quiz.length).padStart(2,'0')}`; $('progress-fill').style.width=`${questionIndex/quiz.length*100}%`; $('quiz-question').textContent=item.question; $('quiz-feedback').textContent=''; $('quiz-options').replaceChildren(); $('quiz-next').hidden=true; $('quiz-finish').hidden=true; item.options.forEach((option,index)=>{const button=document.createElement('button'); button.className='option'; button.textContent=`${String.fromCharCode(65+index)}. ${option}`; button.addEventListener('click',()=>{if(answered)return;answered=true;button.classList.add('selected');[...$('quiz-options').children].forEach(b=>b.disabled=true);$('quiz-feedback').textContent=item.feedback[index];$('progress-fill').style.width=`${(questionIndex+1)/quiz.length*100}%`;hearts(15); if(questionIndex===quiz.length-1){$('quiz-finish').hidden=false;toast('Selamat! Lulus ujian bucin dengan nilai LOVE / 100 💗');} else $('quiz-next').hidden=false;});$('quiz-options').append(button);});}
$('quiz-next').addEventListener('click',()=>{questionIndex++;renderQuiz();$('quiz-options').firstElementChild.focus({preventScroll:true});});
$('quiz-reset').addEventListener('click',()=>{questionIndex=0;renderQuiz();$('quiz-options').firstElementChild.focus({preventScroll:true});});renderQuiz();
const gombals=['Kamu bukan Google, tapi semua yang aku cari ada di kamu.','Kalau kamu jadi Wi-Fi, aku gak mau cari jaringan lain.','Aku bukan astronot, tapi tiap lihat kamu rasanya melayang.','Mareta itu kayak titik koma. Tanpa kamu, hidupku syntax error.','Kalau rindu ini file ZIP, ukurannya tetap tak terhingga.','Aku gak butuh ramalan cuaca. Kalau ada kamu, hariku cerah.','Mareta, kamu bukan tugas kuliah. Tapi aku mikirin kamu terus.','Kalau kamu jadi lagu, tombol repeat-ku pasti rusak.','Jantungku bukan grup WhatsApp, tapi notif kamu bikin rame.','Aku bukan fotografer, tapi masa depanku kebayang sama kamu.','Mareta, kok kamu bisa jadi orang sekaligus alasan senyum?','Kalau kamu senyum, kalkulator aja lupa cara menghitung.']; let gombalIndex=0;
$('gombal-button').addEventListener('click',()=>{gombalIndex=(gombalIndex+1)%gombals.length;$('gombal').textContent=gombals[gombalIndex];hearts(12);});
let loveCount=0;try{const saved=Number(localStorage.getItem('mareta-love-count'));if(Number.isSafeInteger(saved)&&saved>=0)loveCount=saved;}catch{}function updateCount(){ $('love-total').textContent=new Intl.NumberFormat('id-ID').format(loveCount);try{localStorage.setItem('mareta-love-count',String(loveCount));}catch{} }
updateCount();$('love-tap').addEventListener('click',()=>{loveCount=Math.min(loveCount+1,Number.MAX_SAFE_INTEGER);updateCount();hearts(7);if(loveCount%10===0)toast(`${loveCount} sayang terkumpul. Ini bank tanpa bunga, tapi penuh hati. 💗`);});$('counter-reset').addEventListener('click',()=>{loveCount=0;updateCount();toast('Hitungan kembali nol. Sayangnya tetap banyak. ♡');});
$('final-love').addEventListener('click',()=>{ $('final-message').hidden=false; $('final-love').textContent='Paket sayang lagi? Boleh banget! 💕';hearts(75);$('final-message').scrollIntoView({behavior:reducedMotion?'instant':'smooth',block:'center'});});
